	create table t34 as select distinct
	a.*, b.population_growth, b.realgdp_growth, log(Population) as log_population, log(realgdp) as log_realGDP
	from t33 as a left join lib.bea as b on input(a.county_fips,5.0)=input(b.county_fips,5.0) and a.fyear=year2;
quit;

	create table county_finance as select distinct
	a.*, a.total_expenditure/b.total_expenditure-1 as total_expenditure_growth
	from lib.county_finance as a left join lib.county_finance as b on a.FIPS_Combined=b.FIPS_Combined and a.Year4=b.Year4+1
	order by a.FIPS_Combined, a.Year4;
quit;

