	create table lib.msa_polit as select distinct
	a.*, b.ec as ec_lag, b.localrep as localrep_lag, a.localrep-b.localrep as dlocalrep
	from msa_polit as a left join msa_polit as b on a.state=b.state and a.msa=b.msa and a.ec>b.ec
	group by a.state, a.msa, a.ec having a.ec-b.ec=min(a.ec-b.ec);
quit;

